<?php
declare(strict_types=1);
$root=$argv[1];require $root.'/local/bootstrap.php';
use Sokna\Local\Domain\LanStaff\LanStaffRealtimeReceiptService;
use Sokna\Local\Domain\Orders\WaiterCallException;
$cfg=['app'=>['timezone'=>'Asia/Tehran','data_dir'=>sys_get_temp_dir().'/r83-local-'.bin2hex(random_bytes(4))], 'installation'=>['id'=>'r83-test'], 'db'=>['host'=>'127.0.0.1','port'=>(string)(getenv('DB_PORT')?:3306),'name'=>'r83_local','charset'=>'utf8mb4','user'=>'root','pass'=>(string)(getenv('DB_PASSWORD')?:'r83-test')]];
$core=sokna_local_bootstrap($cfg);$core->migrations()->migrate();$p=$core->database();
$results=[];
function check(bool $v,string $name):void{global $results;$results[]=['test'=>$name,'pass'=>$v];if(!$v)throw new RuntimeException($name);}
$user=function(string $name)use($p):array{$p->prepare('INSERT INTO users(username,password_hash,display_name,role,active) VALUES(?,?,?,?,1)')->execute([$name,password_hash('test',PASSWORD_DEFAULT),$name,'admin']);return ['id'=>(int)$p->lastInsertId(),'role'=>'admin','display_name'=>$name];};
$a=$user('r83-a');$b=$user('r83-b');
$p->exec("INSERT INTO categories(category_key,name,audience,sort_order,active) VALUES('r83','R83','guest_staff',10,1)");$cat=(int)$p->lastInsertId();
$item=$core->sellables()->create(['category_id'=>$cat,'name'=>'R83 coffee','price'=>1000,'preparation_station'=>'bar','sellable_kind'=>'menu_item','staff_only'=>false,'takeaway_allowed'=>true]);
$table=function(int $i)use($p):int{$p->prepare('INSERT INTO cafe_tables(name,table_number,code,access_token,active,sort_order) VALUES(?,?,?,?,1,?)')->execute(['R83 '.$i,830+$i,'R83-'.$i,'r83-table-'.$i,$i]);return (int)$p->lastInsertId();};
$t1=$table(1);$t2=$table(2);
$p->exec("INSERT INTO settings(setting_key,setting_value) VALUES('waiter_call_enabled','1') ON DUPLICATE KEY UPDATE setting_value='1'");
$callData=['table_token'=>'r83-table-1','device_token'=>str_repeat('d',32),'client_token'=>str_repeat('c',32)];
$receipt=new LanStaffRealtimeReceiptService($p);
$envelope=fn(string $id,string $kind,array $payload):array=>['request_id'=>$id,'kind'=>$kind,'actor_projection_id'=>'user:'.$a['id'],'created_at'=>gmdate('c'),'expires_at'=>gmdate('c',time()+60),'payload'=>$payload];
$e=$envelope('r83-waiter-create-0001','waiter_call.create',$callData);
$created=$receipt->dispatchAtomic('r83-test',$e,fn()=>$core->waiterCalls()->create($callData));
check($created['state']==='committed','waiter creation and receipt commit atomically');
$again=$receipt->dispatchAtomic('r83-test',$e,fn()=>throw new RuntimeException('must not execute'));
check($again['idempotent']&&$again['result']['call_code']===$created['result']['call_code'],'lost waiter ACK replays exact canonical receipt');
$call=(int)$p->query('SELECT id FROM waiter_calls ORDER BY id DESC LIMIT 1')->fetchColumn();
$core->waiterCallStaff()->changeStatus(['call_id'=>$call,'status'=>'accepted'],$a);
check($core->waiterCallStaff()->changeStatus(['call_id'=>$call,'status'=>'accepted'],$a)['idempotent'],'same waiter acceptance is idempotent');
$blocked=false;try{$core->waiterCallStaff()->changeStatus(['call_id'=>$call,'status'=>'accepted'],$b);}catch(WaiterCallException $x){$blocked=$x->errorCode==='already_accepted';}
check($blocked,'another waiter cannot claim success accepting same call');
check($core->waiterCalls()->cancel($callData+['call_code'=>$created['result']['call_code']])['status']==='unchanged','late guest cancellation cannot cancel accepted call');
check($core->waiterCalls()->status($callData+['call_code'=>$created['result']['call_code']])['status']==='accepted','canonical status survives late cancel');
$blocked=false;try{$d=$callData;$d['table_token']='r83-table-2';$core->waiterCalls()->create($d);}catch(WaiterCallException $x){$blocked=$x->errorCode==='request_id_conflict';}check($blocked,'waiter client token cannot replay another table');
$core->waiterCallStaff()->changeStatus(['call_id'=>$call,'status'=>'completed'],$a);
check($core->waiterCalls()->status($callData+['call_code'=>$created['result']['call_code']])['status']==='completed','terminal call remains queryable from Local');
$order=$core->staffQuickOrders()->commit(['table_id'=>$t1,'expected_session_id'=>0,'request_token'=>'r83-order-00000001','items'=>[['id'=>$item,'quantity'=>1,'expected_price'=>1000]]],$a);
$sid=(int)$order['session_id'];$account=$core->settlements()->account($sid);
$late=['session_id'=>$sid,'request_id'=>'r83-late-000000001','expected_session_id'=>$sid,'expected_remaining_total'=>$account['remaining_total'],'expected_signature'=>$account['signature'],'items'=>[['id'=>$item,'quantity'=>2,'expected_price'=>1000]]];
$beforePrint=(int)$p->query('SELECT COUNT(*) FROM print_jobs')->fetchColumn();
$e=$envelope($late['request_id'],'settlement.late_commit',$late);
$out=$receipt->dispatchAtomic('r83-test',$e,fn()=>$core->lateServed()->commit($late,$a));
check($out['state']==='committed','late-served posting succeeds inside outer receipt transaction');
$after=$core->settlements()->account($sid);
check((int)$after['remaining_total']===(int)$account['remaining_total']+2000,'late-served changes account by exact amount');
check((int)$p->query('SELECT COUNT(*) FROM print_jobs')->fetchColumn()===$beforePrint,'late-served creates no preparation print');
$retry=$receipt->dispatchAtomic('r83-test',$e,fn()=>throw new RuntimeException('replayed handler'));
check($retry['idempotent']&&(int)$retry['result']['order_id']===(int)$out['result']['order_id'],'late-served lost ACK cannot post twice');
check($core->lateServed()->commit($late,$a)['duplicate'],'direct retry replays late-served receipt');
$before=(int)$p->query('SELECT COUNT(*) FROM orders')->fetchColumn();
$bad=$late;$bad['request_id']='r83-rollback-000001';$bad['expected_signature']=$after['signature'];$bad['expected_remaining_total']=$after['remaining_total'];
$e=$envelope($bad['request_id'],'settlement.late_commit',$bad);
$rolled=$receipt->dispatchAtomic('r83-test',$e,function()use($core,$bad,$a){$core->lateServed()->commit($bad,$a);throw new RuntimeException('injected after domain posting');});
check($rolled['state']==='rejected','failure after domain posting is terminal rejection');
check((int)$p->query('SELECT COUNT(*) FROM orders')->fetchColumn()===$before,'outer savepoint rolls back late-served business writes');
check((int)$p->query("SELECT COUNT(*) FROM late_served_accounting_receipts WHERE request_id='r83-rollback-000001'")->fetchColumn()===0,'outer savepoint rolls back domain receipt too');
$dash=$core->reporting()->dashboardSnapshot('2026-11-01');
check(count($dash['daily'])===7,'dashboard emits seven authoritative business dates');
check(array_reduce($dash['daily'],fn($ok,$r)=>$ok&&array_key_exists('net_sales',$r),true),'inactive days have explicit Local zero');
$payload=['session_id'=>$sid,'destination'=>'direct','mode'=>'full','request_id'=>'r83-payment-0000001','expected_session_id'=>$sid,'expected_remaining_total'=>$after['remaining_total'],'expected_signature'=>$after['signature']];
$paid=$core->settlements()->settle($payload,$a);$repaid=$core->settlements()->settle($payload,$a);
check(!empty($repaid['idempotent'])&&$paid['settlement_id']===$repaid['settlement_id'],'lost payment response cannot duplicate settlement');
check($core->settlements()->requestStatus($sid,$payload['request_id'],$a)['state']==='committed','unknown payment outcome resolves canonically');
$publisher=$core->publicEdgePublisher();$rc=new ReflectionClass($publisher);
$record=$rc->getMethod('recordProjectionModelSuccess');$record->invoke($publisher,'operations',20,str_repeat('b',64));$record->invoke($publisher,'operations',10,str_repeat('a',64));
$row=$p->query("SELECT ack_sequence,source_version FROM public_projection_model_delivery WHERE model_key='operations'")->fetch(PDO::FETCH_ASSOC);
check((int)$row['ack_sequence']===20&&$row['source_version']===str_repeat('b',64),'real MariaDB out-of-order ACK preserves sequence/hash pair');
$valid=$rc->getMethod('validProjectionModelAck');
check(!$valid->invoke(null,['ok'=>true,'model_key'=>'operations','ack_sequence'=>21,'source_version'=>str_repeat('b',64)],'operations',20,str_repeat('b',64)),'newer ACK cannot prove older model content');
echo json_encode($results,JSON_PRETTY_PRINT).PHP_EOL;
